INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(15928, 0, 0, 'You are too late!! I... must... obey!!', 14, 0, 100, 0, 0, 8872, 'thaddius SAY_GREET'),
(15928, 1, 0, 'Kill...', 14, 0, 100, 0, 0, 8867, 'thaddius SAY_AGGRO1'),
(15928, 1, 1, 'Eat... your... bones...', 14, 0, 100, 0, 0, 8868, 'thaddius SAY_AGGRO2'),
(15928, 1, 2, 'Break... you!!', 14, 0, 100, 0, 0, 8869, 'thaddius SAY_AGGRO3'),
(15928, 2, 0, 'You... die now!!', 14, 0, 20, 0, 0, 8877, 'thaddius SAY_SLAY'),
(15928, 3, 0, 'Now you feel pain...', 14, 0, 100, 0, 0, 8871, 'thaddius SAY_ELECT'),
(15928, 4, 0, 'Thank... you...', 14, 0, 100, 0, 0, 8870, 'thaddius SAY_DEATH'),
(15928, 5, 0, 'Hurry! Ple-e-ase hurry!!', 14, 0, 100, 0, 0, 8873, 'thaddius SAY_SCREAM1'),
(15928, 5, 1, 'Sto-o-op! Make it stop!!', 14, 0, 100, 0, 0, 8874, 'thaddius SAY_SCREAM2'),
(15928, 5, 2, 'Help me! Save me!', 14, 0, 100, 0, 0, 8875, 'thaddius SAY_SCREAM3'),
(15928, 5, 3, 'No-o-o-o!!', 14, 0, 100, 0, 0, 8876, 'thaddius SAY_SCREAM4'),
(15928, 6, 0, 'The polarity has shifted!', 41, 0, 100, 0, 0, 0, 'Thaddius EMOTE_POLARITY_SHIFTED');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(15929, 0, 0, 'Stalagg crush you!', 14, 0, 100, 0, 0, 8864, 'stalagg SAY_STAL_AGGRO'),
(15929, 1, 0, 'Stalagg kill!', 14, 0, 20, 0, 0, 8866, 'stalagg SAY_STAL_SLAY'),
(15929, 2, 0, 'Master, save me!!', 14, 0, 100, 0, 0, 8865, 'stalagg SAY_STAL_DEATH'),
(15929, 3, 0, '%s dies.', 16, 0, 100, 0, 0, 0, 'Stalagg EMOTE_FEIGN_DEATH'),
(15929, 4, 0, '%s is jolted back to life!', 16, 0, 100, 0, 0, 0, 'Stalagg EMOTE_FEIGN_REVIVE');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(15930, 0, 0, 'Feed you to master!', 14, 0, 100, 0, 0, 8802, 'feugen SAY_FEUG_AGGRO'),
(15930, 1, 0, 'Feugen make master happy.', 14, 0, 20, 0, 0, 8804, 'feugen SAY_FEUG_SLAY'),
(15930, 2, 0, 'No... more... Feugen.', 14, 0, 100, 0, 0, 8803, 'feugen SAY_FEUG_DEATH'),
(15930, 3, 0, '%s dies.', 16, 0, 100, 0, 0, 0, 'Feugen EMOTE_FEIGN_DEATH'),
(15930, 4, 0, '%s is jolted back to life!', 16, 0, 100, 0, 0, 0, 'Feugen EMOTE_FEIGN_REVIVE');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(15932, 0, 0, '%s spots a zombie to devour!', 16, 0, 100, 0, 0, 0, 'Gluth - spots one'),
(15932, 1, 0, '%s decimates all nearby flesh!', 41, 0, 100, 0, 0, 0, 'Gluth - decimate'),
(15932, 2, 0, '%s becomes enraged!', 41, 0, 100, 0, 0, 0, 'Gluth - enrage'),
(15932, 3, 0, '%s devours all nearby zombies!', 16, 0, 100, 0, 0, 0, 'Gluth - devours all'),
(15932, 4, 0, '%s goes into a berserker rage!', 41, 0, 100, 0, 0, 0, 'Gluth - berserker');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(15936, 0, 0, 'You are mine now.', 14, 0, 100, 0, 0, 8825, 'heigan SAY_AGGRO1'),
(15936, 0, 1, 'I see you!', 14, 0, 100, 0, 0, 8826, 'heigan SAY_AGGRO2'),
(15936, 0, 2, 'You... are next.', 14, 0, 100, 0, 0, 8827, 'heigan SAY_AGGRO3'),
(15936, 1, 0, 'Close your eyes. Sleep.', 14, 0, 20, 0, 0, 8829, 'heigan SAY_SLAY'),
(15936, 2, 0, 'The races of the world will perish. It is only a matter of time.', 14, 0, 100, 0, 0, 8830, 'heigan SAY_TAUNT1'),
(15936, 2, 1, 'I see endless suffering. I see torment. I see rage. I see everything...', 14, 0, 100, 0, 0, 8831, 'heigan SAY_TAUNT2'),
(15936, 2, 2, 'Soon the world will tremble.', 14, 0, 100, 0, 0, 8832, 'heigan SAY_TAUNT3'),
(15936, 2, 3, 'The end is upon you.', 14, 0, 100, 0, 0, 8833, 'heigan SAY_TAUNT4'),
(15936, 2, 4, 'Hungry worms will feast on your rotting flesh.', 14, 0, 100, 0, 0, 8834, 'heigan SAY_TAUNT5'),
(15936, 3, 0, 'Noo... o...', 14, 0, 100, 0, 0, 8828, 'heigan SAY_DEATH'),
(15936, 4, 0, '%s teleports and begins to channel a spell!', 41, 0, 100, 0, 0, 0, 'Heigan EMOTE_DANCE'),
(15936, 5, 0, '%s rushes to attack once more!', 41, 0, 100, 0, 0, 0, 'Heigan EMOTE_DANCE_END');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(15952, 0, 0, 'Spiderlings appear on the web!', 41, 0, 100, 0, 0, 0, 'Maexxna EMOTE_SPIDERS'),
(15952, 1, 0, '%s spins her web into a cocoon!', 41, 0, 100, 0, 0, 0, 'Maexxna EMOTE_WEB_WRAP'),
(15952, 2, 0, '%s sprays strands of web everywhere!', 41, 0, 100, 0, 0, 0, 'Maexxna EMOTE_WEB_SPRAY');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(15953, 0, 0, 'Your old lives, your mortal desires mean nothing... you are acolytes of the master now, and you will serve the cause without question! The greatest glory is to die in the master\'s service!', 14, 0, 100, 0, 0, 8799, 'faerlina SAY_GREET'),
(15953, 1, 0, 'Slay them in the master\'s name!', 14, 0, 100, 0, 0, 8794, 'faerlina SAY_AGGRO1'),
(15953, 1, 1, 'You cannot hide from me!', 14, 0, 100, 0, 0, 8795, 'faerlina SAY_AGGRO2'),
(15953, 1, 2, 'Kneel before me, worm!', 14, 0, 100, 0, 0, 8796, 'faerlina SAY_AGGRO3'),
(15953, 1, 3, 'Run while you still can!', 14, 0, 100, 0, 0, 8797, 'faerlina SAY_AGGRO4'),
(15953, 2, 0, 'You have failed!', 14, 0, 16, 0, 0, 8800, 'faerlina SAY_SLAY1'),
(15953, 2, 1, 'Pathetic wretch!', 14, 0, 16, 0, 0, 8801, 'faerlina SAY_SLAY2'),
(15953, 3, 0, 'The master will avenge me!!', 14, 0, 100, 0, 0, 8798, 'faerlina SAY_DEATH'),
(15953, 4, 0, '%s is affected by Widow\'s Embrace!', 41, 0, 100, 0, 0, 0, 'Faerlina EMOTE_WIDOW_EMBRACE'),
(15953, 5, 0, '%s goes into a frenzy!', 41, 0, 100, 0, 0, 0, 'Faerlina EMOTE_FRENZY');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(15954, 0, 0, 'Glory to the master!', 14, 0, 100, 0, 0, 8845, 'noth SAY_AGGRO1'),
(15954, 0, 1, 'Your life is forfeit!', 14, 0, 100, 0, 0, 8846, 'noth SAY_AGGRO2'),
(15954, 0, 2, 'Die, trespasser!', 14, 0, 100, 0, 0, 8847, 'noth SAY_AGGRO3'),
(15954, 1, 0, 'Rise, my soldiers! Rise and fight once more!', 14, 0, 100, 0, 0, 8851, 'noth SAY_SUMMON'),
(15954, 2, 0, 'My task is done!', 14, 0, 20, 0, 0, 8849, 'noth SAY_SLAY1'),
(15954, 2, 1, 'Breathe no more!', 14, 0, 20, 0, 0, 8850, 'noth SAY_SLAY2'),
(15954, 3, 0, 'I will serve the master... in death!', 14, 0, 100, 0, 0, 8848, 'noth SAY_DEATH'),
(15954, 4, 0, '%s summons forth Skeletal Warriors!', 41, 0, 100, 0, 0, 0, 'Noth EMOTE_SUMMON'),
(15954, 5, 0, '%s raises more skeletons!', 41, 0, 100, 0, 0, 0, 'Noth EMOTE_SUMMON_WAVE'),
(15954, 6, 0, '%s teleports to the balcony above!', 41, 0, 100, 0, 0, 0, 'Noth EMOTE_TELEPORT_1'),
(15954, 7, 0, '%s teleports back into the battle!', 41, 0, 100, 0, 0, 0, 'Noth EMOTE_TELEPORT_2');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(15956, 0, 0, 'Just a little taste...', 14, 0, 100, 0, 0, 8785, 'anubrekhan SAY_AGGRO1'),
(15956, 0, 1, 'There is no way out.', 14, 0, 100, 0, 0, 8786, 'anubrekhan SAY_AGGRO2'),
(15956, 0, 2, 'Yes, run! It makes the blood pump faster!', 14, 0, 100, 0, 0, 8787, 'anubrekhan SAY_AGGRO3'),
(15956, 1, 0, 'Ahh... welcome to my parlor.', 14, 0, 100, 0, 0, 8788, 'anubrekhan SAY_GREET1'),
(15956, 1, 1, 'I hear little hearts beating. Yes... beating faster now... soon the beating will stop.', 14, 0, 100, 0, 0, 8790, 'anubrekhan SAY_GREET2'),
(15956, 1, 2, 'Where to go? What to do? So many choices that all end in pain, end in death.', 14, 0, 100, 0, 0, 8791, 'anubrekhan SAY_GREET3'),
(15956, 1, 3, 'Which one shall I eat first? So difficult to choose. They all smell so delicious...', 14, 0, 100, 0, 0, 8792, 'anubrekhan SAY_GREET4'),
(15956, 1, 4, 'Closer now. Tasty morsels. I\'ve been too long without food, without blood to drink.', 14, 0, 100, 0, 0, 8793, 'anubrekhan SAY_GREET5'),
(15956, 2, 0, 'Shhh... it will all be over soon.', 14, 0, 100, 0, 0, 8789, 'anubrekhan SAY_SLAY'),
(15956, 3, 0, 'Anub\'Rekhan begins to unleash an insect swarm!', 41, 0, 100, 0, 0, 0, 'Anub\'Rekhan EMOTE_LOCUST');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(15990, 0, 0, 'Your forces are nearly marshaled to strike back against your enemies, my liege.', 14, 0, 100, 0, 0, 14467, 'kelthuzad SAY_SAPP_DIALOG1'),
(15990, 1, 0, 'It is good that you serve me so faithfully. Soon, all will serve the Lich King and in the end, you shall be rewarded...so long as you do not falter.', 14, 0, 100, 0, 0, 8881, 'kelthuzad SAY_SAPP_DIALOG2_LICH'),
(15990, 2, 0, 'Yes, master. The time of their ultimate demise draws close.... What is this?', 14, 0, 100, 0, 0, 14468, 'kelthuzad SAY_SAPP_DIALOG3'),
(15990, 3, 0, 'Your security measures have failed! See to this interruption immediately!', 14, 0, 100, 0, 0, 8882, 'kelthuzad SAY_SAPP_DIALOG4_LICH'),
(15990, 4, 0, 'As you command, master!', 14, 0, 100, 0, 0, 14469, 'kelthuzad SAY_SAPP_DIALOG5'),
(15990, 5, 0, 'No!!! A curse upon you, interlopers! The armies of the Lich King will hunt you down. You will not escape your fate...', 14, 0, 100, 0, 0, 14484, 'kelthuzad SAY_CAT_DIED'),
(15990, 6, 0, '', 14, 0, 100, 0, 0, 14463, 'kelthuzad SAY_TAUNT1'),
(15990, 6, 1, 'Fools! You think yourselves triumphant? You have only taken one step closer to the abyss!', 14, 0, 100, 0, 0, 14464, 'kelthuzad SAY_TAUNT2'),
(15990, 6, 2, 'I grow tired of these games. Proceed, and I will banish your souls to oblivion!', 14, 0, 100, 0, 0, 14465, 'kelthuzad SAY_TAUNT3'),
(15990, 6, 3, 'You have no idea what horrors lie ahead. You have seen nothing! The frozen heart of Naxxramas awaits you!', 14, 0, 100, 0, 0, 14466, 'kelthuzad SAY_TAUNT4'),
(15990, 7, 0, 'Pray for mercy!', 14, 0, 100, 0, 0, 14475, 'kelthuzad SAY_AGGRO1'),
(15990, 7, 1, 'Scream your dying breath!', 14, 0, 100, 0, 0, 14476, 'kelthuzad SAY_AGGRO2'),
(15990, 7, 2, 'The end is upon you!', 14, 0, 100, 0, 0, 14477, 'kelthuzad SAY_AGGRO3'),
(15990, 8, 0, 'The dark void awaits you!', 14, 0, 100, 0, 0, 14478, 'kelthuzad SAY_SLAY1'),
(15990, 8, 1, '%s cackles maniacally.', 16, 0, 100, 0, 0, 14479, 'kelthuzad SAY_SLAY2'),
(15990, 9, 0, 'Agghhhh! Do... not... rejoice! Your victory is a hollow one, for I shall return with powers beyond your imagining!', 14, 0, 100, 0, 0, 14480, 'kelthuzad SAY_DEATH'),
(15990, 10, 0, 'Your soul is bound to me, now!', 14, 0, 100, 0, 0, 14472, 'kelthuzad SAY_CHAIN1'),
(15990, 10, 1, 'There will be no escape!', 14, 0, 100, 0, 0, 14473, 'kelthuzad SAY_CHAIN2'),
(15990, 11, 0, 'I will freeze the blood in your veins!', 14, 0, 100, 0, 0, 14474, 'kelthuzad SAY_FROST_BLAST'),
(15990, 12, 0, 'Master, I require aid!', 14, 0, 100, 0, 0, 14470, 'kelthuzad SAY_REQUEST_AID'),
(15990, 13, 0, 'Kel\'Thuzad strikes!', 41, 0, 100, 0, 0, 0, 'Kel\'Thuzad EMOTE_PHASE_TWO'),
(15990, 14, 0, 'Minions, servants, soldiers of the cold dark! Obey the call of Kel\'Thuzad!', 14, 0, 100, 0, 0, 14471, 'kelthuzad SAY_SUMMON_MINIONS'),
(15990, 15, 0, 'Your petty magics are no challenge to the might of the Scourge!', 14, 0, 100, 0, 0, 14481, 'kelthuzad SAY_SPECIAL1_MANA_DET'),
(15990, 15, 1, 'Enough! I grow tired of these distractions! ', 14, 0, 100, 0, 0, 14483, 'kelthuzad SAY_SPECIAL3_MANA_DET'),
(15990, 15, 2, 'Fools, you have spread your powers too thin. Be free, my minions!', 14, 0, 100, 0, 0, 14482, 'kelthuzad SAY_SPECIAL2_DISPELL'),
(15990, 16, 0, 'Who dares violate the sanctity of my domain? Be warned, all who trespass here are doomed.', 14, 0, 100, 0, 0, 14463, 'kelthuzad SAY_TAUNT1'),
(15990, 17, 0, 'Fools! You think yourselves triumphant? You have only taken one step closer to the abyss!', 14, 0, 100, 0, 0, 14464, 'kelthuzad SAY_TAUNT2'),
(15990, 18, 0, 'I grow tired of these games. Proceed, and I will banish your souls to oblivion!', 14, 0, 100, 0, 0, 14465, 'kelthuzad SAY_TAUNT3'),
(15990, 19, 0, 'You have no idea what horrors lie ahead. You have seen nothing! The frozen heart of Naxxramas awaits you!', 14, 0, 100, 0, 0, 14466, 'kelthuzad SAY_TAUNT4'),
(15990, 20, 0, 'Come, heroes... By the will of the Lich King, you shall be destroyed.', 14, 0, 100, 0, 0, 0, 'Kel\'Thuzad SAY_DIALOGUE_SAPPHIRON_KELTHUZAD4');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(16011, 0, 0, 'An aura of necrotic energy blocks all healing!', 41, 0, 100, 0, 0, 0, 'Loatheb'),
(16011, 1, 0, 'The aura fades away, allowing healing once more!', 41, 0, 100, 0, 0, 0, 'Loatheb'),
(16011, 2, 0, 'The aura\'s power begins to wane!', 41, 0, 100, 0, 0, 0, 'Loatheb');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(16028, 0, 0, 'Patchwerk want to play!', 14, 0, 100, 0, 0, 8909, 'patchwerk SAY_AGGRO1'),
(16028, 0, 1, 'Kel\'thuzad make Patchwerk his avatar of war!', 14, 0, 100, 0, 0, 8910, 'patchwerk SAY_AGGRO2'),
(16028, 1, 0, 'No more play?', 14, 0, 100, 0, 0, 8912, 'patchwerk SAY_SLAY'),
(16028, 2, 0, 'What... happen to-', 14, 0, 100, 0, 0, 8911, 'patchwerk SAY_DEATH'),
(16028, 3, 0, '%s goes into a berserker rage!', 16, 0, 100, 0, 0, 0, 'patchwerk EMOTE_BERSERK'),
(16028, 4, 0, '%s goes into a frenzy!', 41, 0, 100, 0, 0, 0, 'patchwerk EMOTE_ENRAGE');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(16060, 0, 0, 'Foolishly you have sought your own demise.', 14, 0, 100, 0, 0, 8807, 'Gothik SAY_INTRO_1'),
(16060, 1, 0, 'Brazenly you have disregarded powers beyond your understanding.', 14, 0, 100, 0, 0, 0, 'Gothik SAY_INTRO_2'),
(16060, 2, 0, 'You have fought hard to invade the realm of the harvester.', 14, 0, 100, 0, 0, 0, 'Gothik SAY_INTRO_3'),
(16060, 3, 0, 'Now there is only one way out- to walk the lonely path of the damned.', 14, 0, 100, 0, 0, 0, 'Gothik SAY_INTRO_4'),
(16060, 4, 0, 'I have waited long enough. Now you face the harvester of souls.', 14, 0, 100, 0, 0, 8808, 'Gothik SAY_PHASE_TWO'),
(16060, 5, 0, 'I... am... undone.', 14, 0, 100, 0, 0, 8805, 'Gothik SAY_DEATH'),
(16060, 6, 0, 'Death is the only escape!', 14, 0, 20, 0, 0, 8806, 'Gothik SAY_KILL'),
(16060, 7, 0, '%s teleports into the fray!', 41, 0, 100, 0, 0, 0, 'Gothik EMOTE_PHASE_TWO'),
(16060, 8, 0, 'The central gate opens!', 41, 0, 100, 0, 0, 0, 'Gothik EMOTE_GATE_OPENED');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(16061, 0, 0, 'Do as I taught you!', 14, 0, 100, 0, 0, 8855, 'Razuvious SAY_AGGRO #1'),
(16061, 0, 1, 'The time for practice is over! Show me what you have learned!', 14, 0, 100, 0, 0, 8859, 'Razuvious SAY_AGGRO #2'),
(16061, 0, 2, 'Show them no mercy!', 14, 0, 100, 0, 0, 8856, 'Razuvious SAY_AGGRO #3'),
(16061, 1, 0, '%s lets loose a triumphant shout.', 41, 0, 30, 0, 0, 0, 'Razuvious SAY_SLAY'),
(16061, 2, 0, 'You should have stayed home.', 14, 0, 50, 0, 0, 8861, 'Razuvious SAY_TAUNTED #1'),
(16061, 2, 1, 'You disappoint me, students!', 14, 0, 50, 0, 0, 8858, 'Razuvious SAY_TAUNTED #2'),
(16061, 2, 2, 'I\'m just getting warmed up!', 14, 0, 50, 0, 0, 8852, 'Razuvious SAY_TAUNTED #3'),
(16061, 2, 3, 'Stand and fight!', 14, 0, 50, 0, 0, 8853, 'Razuvious SAY_TAUNTED #4'),
(16061, 2, 4, 'Sweep the leg... Do you have a problem with that?', 14, 0, 50, 0, 0, 8861, 'Razuvious SAY_TAUNTED #5'),
(16061, 3, 0, 'An honorable... death.', 14, 0, 100, 0, 0, 8860, 'Razuvious SAY_DEATH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(16063, 0, 0, 'Flee, before it\'s too late!', 14, 0, 100, 0, 0, 8913, 'zeliek SAY_ZELI_AGGRO'),
(16063, 1, 0, 'Invaders, cease this foolish venture at once! Turn away while you still can!', 14, 0, 100, 0, 0, 8917, 'zeliek SAY_ZELI_TAUNT1'),
(16063, 1, 1, 'Perhaps they will come to their senses... and run away as fast as they can.', 14, 0, 100, 0, 0, 8918, 'zeliek SAY_ZELI_TAUNT2'),
(16063, 1, 2, 'Do not continue! Turn back while there\'s still time!', 14, 0, 100, 0, 0, 8919, 'zeliek SAY_ZELI_TAUNT3'),
(16063, 2, 0, 'I have no choice but to obey!', 14, 0, 100, 0, 0, 8916, 'zeliek SAY_ZELI_SPECIAL'),
(16063, 3, 0, 'Forgive me!', 14, 0, 30, 0, 0, 8915, 'zeliek SAY_ZELI_SLAY'),
(16063, 4, 0, 'It is... as it should be. ', 14, 0, 100, 0, 0, 8914, 'zeliek SAY_ZELI_DEATH'),
(16063, 5, 0, 'Invaders, cease this foolish venture at once! Turn away while you still can!', 14, 0, 100, 0, 0, 8917, 'zeliek SAY_ZELI_TAUNT1'),
(16063, 6, 0, 'Perhaps they will come to their senses... and run away as fast as they can.', 14, 0, 100, 0, 0, 8918, 'zeliek SAY_ZELI_TAUNT2'),
(16063, 7, 0, '%s casts Condemnation on everyone!', 41, 0, 100, 0, 0, 0, 'zeliek EMOTE_RAGECAST');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(16064, 0, 0, 'C\'mon an\' fight ye wee ninny!', 14, 0, 100, 0, 0, 8899, 'korthazz SAY_KORT_AGGRO'),
(16064, 1, 0, 'To arms, ye roustabouts! We\'ve got company!', 14, 0, 100, 0, 0, 8903, 'korthazz SAY_KORT_TAUNT1'),
(16064, 1, 1, 'I\'ve heard about enough a\' yer snivelin\'! Shut yer flytrap before I shut it for ye\'!', 14, 0, 100, 0, 0, 8904, 'korthazz SAY_KORT_TAUNT2'),
(16064, 1, 2, 'I\'m gonna\' enjoy killin\' these slack-jawed daffodils!', 14, 0, 100, 0, 0, 8905, 'korthazz SAY_KORT_TAUNT3'),
(16064, 2, 0, 'I like my meat extra crispy!', 14, 0, 100, 0, 0, 8902, 'korthazz SAY_KORT_SPECIAl'),
(16064, 3, 0, 'Next time, bring more friends!', 14, 0, 30, 0, 0, 8901, 'korthazz SAY_KORT_SLAY'),
(16064, 4, 0, 'What a bloody waste this is!', 14, 0, 100, 0, 0, 8900, 'korthazz SAY_KORT_DEATH'),
(16064, 5, 0, 'To arms, ye roustabouts! We\'ve got company!', 14, 0, 100, 0, 0, 8903, 'korthazz SAY_KORT_TAUNT1'),
(16064, 6, 0, 'I\'ve heard about enough a\' yer snivelin\'! Shut yer flytrap before I shut it for ye\'!', 14, 0, 100, 0, 0, 8904, 'korthazz SAY_KORT_TAUNT2');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(16065, 0, 0, 'Defend yourself!', 14, 0, 100, 0, 0, 8892, 'blaumeux SAY_BLAU_AGGRO'),
(16065, 1, 0, 'Come, Zeliek, do not drive them out. Not before we\'ve had our fun!', 14, 0, 100, 0, 0, 8896, 'blaumeux SAY_BLAU_TAUNT1'),
(16065, 1, 1, 'I do hope they stay alive long enough for me to... introduce myself.', 14, 0, 100, 0, 0, 8897, 'blaumeux SAY_BLAU_TAUNT2'),
(16065, 1, 2, 'The first kill goes to me! Anyone care to wager?', 14, 0, 100, 0, 0, 8898, 'blaumeux SAY_BLAU_TAUNT3'),
(16065, 2, 0, 'Your life is mine!', 14, 0, 100, 0, 0, 8895, 'blaumeux SAY_BLAU_SPECIAL'),
(16065, 3, 0, 'Who\'s next?', 14, 0, 30, 0, 0, 8894, 'blaumeux SAY_BLAU_SLAY'),
(16065, 4, 0, 'Touche...', 14, 0, 100, 0, 0, 8893, 'blaumeux SAY_BLAU_DEATH'),
(16065, 5, 0, 'Come, Zeliek, do not drive them out. Not before we\'ve had our fun!', 14, 0, 100, 0, 0, 8896, 'blaumeux SAY_BLAU_TAUNT1'),
(16065, 6, 0, 'I do hope they stay alive long enough for me to... introduce myself.', 14, 0, 100, 0, 0, 8897, 'blaumeux SAY_BLAU_TAUNT2'),
(16065, 7, 0, '%s casts Unyielding Pain on everyone!', 41, 0, 100, 0, 0, 0, 'blaumeux EMOTE_RAGECAST');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(30549, 0, 0, 'You seek death?', 14, 0, 100, 0, 0, 14571, 'rivendare SAY_RIVE_AGGRO1'),
(30549, 0, 1, 'None shall pass!', 14, 0, 100, 0, 0, 14572, 'rivendare SAY_RIVE_AGGRO2'),
(30549, 0, 2, 'Be still!', 14, 0, 100, 0, 0, 14573, 'rivendare SAY_RIVE_AGGRO3'),
(30549, 1, 0, 'Enough prattling. Let them come. We shall grind their bones to dust.', 14, 0, 100, 0, 0, 14577, 'rivendare SAY_RIVE_TAUNT1'),
(30549, 1, 1, 'Conserve your anger. Harness your rage. You will all have outlets for your frustrations soon enough.', 14, 0, 100, 0, 0, 14578, 'rivendare SAY_RIVE_TAUNT2'),
(30549, 1, 2, 'Life is meaningless. It is in death that we are truly tested.', 14, 0, 100, 0, 0, 14579, 'rivendare SAY_RIVE_TAUNT3'),
(30549, 2, 0, 'Bow to the might of the Scourge!', 14, 0, 100, 0, 0, 14576, 'rivendare SAY_RIVE_SPECIAL'),
(30549, 3, 0, 'You will find no peace in death.', 14, 0, 30, 0, 0, 14574, 'rivendare SAY_RIVE_SLAY1'),
(30549, 3, 1, 'The master\'s will is done.', 14, 0, 30, 0, 0, 14575, 'rivendare SAY_RIVE_SLAY2'),
(30549, 4, 0, 'Death... will not stop me.', 14, 0, 100, 0, 0, 14580, 'rivendare SAY_RIVE_DEATH'),
(30549, 5, 0, 'Enough prattling. Let them come. We shall grind their bones to dust.', 14, 0, 100, 0, 0, 14577, 'rivendare SAY_RIVE_TAUNT1'),
(30549, 6, 0, 'Conserve your anger. Harness your rage. You will all have outlets for your frustrations soon enough.', 14, 0, 100, 0, 0, 14578, 'rivendare SAY_RIVE_TAUNT2');
